import{_ as t,o as i,c as a,ae as r}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"🛡️ Secure Coding Practices - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/secure_coding_practices.md","filePath":"standards/secure_coding_practices.md"}'),n={name:"standards/secure_coding_practices.md"};function o(s,e,c,l,d,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="🛡️-secure-coding-practices-tendercheck-ai" tabindex="-1">🛡️ Secure Coding Practices - TenderCheck AI <a class="header-anchor" href="#🛡️-secure-coding-practices-tendercheck-ai" aria-label="Permalink to &quot;🛡️ Secure Coding Practices - TenderCheck AI&quot;">​</a></h1><h2 id="_1-input-validation-data-integrity" tabindex="-1">1. Input Validation &amp; Data Integrity <a class="header-anchor" href="#_1-input-validation-data-integrity" aria-label="Permalink to &quot;1. Input Validation &amp; Data Integrity&quot;">​</a></h2><ul><li>[cite_start]<strong>Strict Validation</strong>: Every piece of external data (API requests, PDF text) must be validated using <strong>Zod</strong> or <strong>Valibot</strong> schemas to prevent malformed data from reaching the domain[cite: 667].</li><li>[cite_start]<strong>Type Safety</strong>: Leverage TypeScript&#39;s strict mode to eliminate null pointer exceptions and ensure data consistency[cite: 498].</li><li>[cite_start]<strong>File Upload Security</strong>: Validate PDF file types and sizes at the infrastructure level before processing[cite: 1135].</li></ul><h2 id="_2-mitigation-of-common-vulnerabilities-owasp-top-10" tabindex="-1">2. Mitigation of Common Vulnerabilities (OWASP Top 10) <a class="header-anchor" href="#_2-mitigation-of-common-vulnerabilities-owasp-top-10" aria-label="Permalink to &quot;2. Mitigation of Common Vulnerabilities (OWASP Top 10)&quot;">​</a></h2><ul><li>[cite_start]<strong>XSS Prevention</strong>: Sanitize and encode all data before rendering it in the UI to prevent Cross-Site Scripting[cite: 206, 217].</li><li>[cite_start]<strong>Injection Defense</strong>: Use parameterized logic and avoid dynamic string concatenation for system commands or database queries[cite: 668].</li><li>[cite_start]<strong>Secure Headers</strong>: Implement <strong>Helmet.js</strong> to set critical security headers like Content-Security-Policy (CSP) and X-Content-Type-Options[cite: 170, 218].</li></ul><h2 id="_3-secure-ai-llm-implementation" tabindex="-1">3. Secure AI &amp; LLM Implementation <a class="header-anchor" href="#_3-secure-ai-llm-implementation" aria-label="Permalink to &quot;3. Secure AI &amp; LLM Implementation&quot;">​</a></h2><ul><li>[cite_start]<strong>Prompt Injection Defense</strong>: Design prompts that isolate user-provided text (from PDFs) from system instructions[cite: 728].</li><li>[cite_start]<strong>Data Privacy</strong>: Ensure sensitive information extracted from documents is never logged or used as training data for external LLMs[cite: 573].</li><li>[cite_start]<strong>Traceable Decisions</strong>: Every AI output must be audited for accuracy and security before being presented as a &quot;ValidationResult&quot;[cite: 732, 1223].</li></ul><h2 id="_4-authentication-secret-management" tabindex="-1">4. Authentication &amp; Secret Management <a class="header-anchor" href="#_4-authentication-secret-management" aria-label="Permalink to &quot;4. Authentication &amp; Secret Management&quot;">​</a></h2><ul><li>[cite_start]<strong>Secrets Control</strong>: Never commit API keys or credentials; use <code>.env</code> files validated at runtime[cite: 667].</li><li>[cite_start]<strong>Secure Sessions</strong>: Use <strong>JWT</strong> with short expiration times and <strong>Bcrypt</strong> for hashing if storing user credentials[cite: 171, 668].</li></ul><h2 id="_5-secure-infrastructure-audit" tabindex="-1">5. Secure Infrastructure &amp; Audit <a class="header-anchor" href="#_5-secure-infrastructure-audit" aria-label="Permalink to &quot;5. Secure Infrastructure &amp; Audit&quot;">​</a></h2><ul><li><strong>Hardened Containers</strong>: Use minimal Docker images to reduce the attack surface and potential CVEs.</li><li>[cite_start]<strong>Automated Auditing</strong>: Use tools like <strong>CodeRabbit</strong> or <strong>Snyk</strong> to review code for security flaws during PRs[cite: 613, 618].</li><li>[cite_start]<strong>Dependency Hygiene</strong>: Regularly run <code>npm audit</code> and keep dependencies updated via <strong>Dependabot</strong>[cite: 218].</li></ul>',11)])])}const p=t(n,[["render",o]]);export{m as __pageData,p as default};
